sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.requestAsset = function(asset) {
    c.data.selectedAsset = asset;
    c.data.showModal = true;
  };

  c.closeModal = function() {
    c.data.showModal = false;
  };

  c.confirmRequest = function() {
    alert("Request submitted for: " + c.data.selectedAsset.name);
    c.closeModal();
  };
};

sp_widget.css:
.asset-grid {
  width: 86%;
  max-width: 1200px;
  margin: 0 auto 40px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}

.asset-card {
  background: #fff;
  border: 1px solid #e0e0e0;
  border-radius: 4px;
  padding: 22px;
  text-align: center;
}

.asset-card-icon {
  font-size: 32px;
  margin-bottom: 10px;
}

.asset-card h4 {
  font-size: 15px;
  color: #333;
  margin: 0 0 8px;
}

.asset-meta {
  font-size: 12.5px;
  color: #777;
  margin-bottom: 4px;
}

.asset-card button {
  margin-top: 14px;
  width: 100%;
  padding: 10px;
  font-size: 13px;
  background: #e60028;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.asset-card button:hover {
  opacity: 0.9;
}

@media (max-width: 768px) {
  .asset-grid {
    grid-template-columns: 1fr;
  }
}

